//! Fixed body captured in two Camp08 runs, not generated by a Rust encoder.
//! CP306: g1-camp08-boundary.json; native writer B731D0 and getter agree.
//! Retained native122-verification.json: sequence 184, body SHA-256
//! 9094bdd30cf13d00cc1d65320af7fe631c23f4f6822cd337e3cce7856ee01e8a.
//! This fixture proves the measured layout only; serving/authority is separate.
use kr_wire::kr00967::{BombReport122, bomb_report122};

const BODY: [u8; 17] = [
    0x69, 0x35, 0xac, 0x6a, 0xa5, 0x6f, 0xa5, 0x6b, 0x96, 0xca, 0x53, 0x91, 0xa5, 0x96, 0xca, 0x53,
    0x95,
];

#[test]
fn native_writer_body_preserves_sentinel_and_measured_field_widths() {
    assert_eq!(
        bomb_report122(&BODY).unwrap(),
        BombReport122 {
            property: u32::MAX,
            row: 6,
            column: 2,
            reason: 4,
            auxiliary: u8::MAX,
            trailing: 0,
        }
    );
}

#[test]
fn partial_body_or_trailer_is_never_silently_consumed() {
    for length in 0..BODY.len() {
        assert!(bomb_report122(&BODY[..length]).is_err());
    }
    let mut extra = BODY.to_vec();
    extra.push(0);
    assert!(bomb_report122(&extra).is_err());
    assert!(bomb_report122(&[0; 4096]).is_err());
}
